// Bridges OpenNext's `CloudflareEnv` global to the bindings generated by
// `wrangler types` into worker-configuration.d.ts (run `npm run cf-typegen`
// after changing wrangler.jsonc). Runtime secrets are set via
// `wrangler secret put`, so they aren't in wrangler.jsonc and must be
// declared here.

interface CloudflareEnv extends Cloudflare.Env {
  /** OAuth web client id for signing in with Google. */
  GOOGLE_OAUTH_CLIENT_ID: string;
  /** OAuth web client secret (server-side only). */
  GOOGLE_OAUTH_CLIENT_SECRET: string;
  /** Secret that signs the session cookie. Required: with none, signing in is refused. */
  SESSION_SECRET: string;
  /** The Web Push VAPID public key: the uncompressed P-256 point, base64url. */
  VAPID_PUBLIC_KEY: string;
  /** The Web Push VAPID private key: the P-256 scalar, base64url. */
  VAPID_PRIVATE_KEY: string;
  /**
   * Cloudflare Email Sending, for emailing a story. Optional: until the domain
   * is onboarded and the `send_email` binding is added, the API answers 503
   * and the app offers a mailto link instead.
   */
  EMAIL?: SendEmail;
  /**
   * Article embeddings, for clustering the same story from different sources.
   * Optional and off by default: until the index is created and the
   * `vectorize` binding is added to wrangler.jsonc, clustering is skipped.
   */
  VECTORIZE?: VectorizeIndex;
  /** The address stories are emailed from, on the onboarded domain. */
  EMAIL_FROM?: string;
  /**
   * Public origin, e.g. https://broadsheet.apps.mrida.ng. Optional; derived
   * from the request when unset (local dev).
   */
  APP_URL?: string;
}
